"""Wide forward range iteration, compared with bounded CPython results."""

def observe(values):
    iterator = iter(values)
    hints = [iterator.__length_hint__()]
    found = []
    # Every test range contains at most sixteen elements. Bound the drive loop
    # even if the implementation fails to exhaust after its final valid value.
    for i in range(20):
        try:
            found.append(next(iterator))
        except StopIteration:
            break
        hints.append(iterator.__length_hint__())
    ended = []
    for i in range(2):
        try:
            next(iterator)
            ended.append(False)
        except StopIteration:
            ended.append(True)
    return found, hints, ended

def pickle_rest(values):
    import pickle
    iterator = iter(values)
    next(iterator, None)
    copies = [pickle.loads(pickle.dumps(iterator, protocol=p)) for p in (0, 4, 5)]
    return [list(v) for v in copies]

