for name, call, expected in CASES:
    try:
        value = call()
        actual = ('ok', type(value).__name__, repr(value))
    except Exception as error:
        actual = ('err', type(error).__name__, str(error))
    assert actual == expected, (name, actual, expected)
print('ok')
